function progCode(programa) {
  const p = String(programa || '').toLowerCase();
  if (/internado|boarding/.test(p)) return 'bs';
  if (/intercambio|familia| aa |a[nñ]o acad/.test(p)) return 'aa';
  if (/campament|summer/.test(p)) return 'sc';
  if (/pathway|alemania/.test(p)) return 'ptw';
  if (/gap|hapy|happy|estudi.*trabaj/.test(p)) return 'gy';
  return 'gen';
}
function elegirPlantilla(lane, toques, programa) {
  const pc = progCode(programa);
  const d1 = pc === 'sc' ? 'seguimiento_dia_1_plantilla_sc' : 'seguimiento_dia_1_' + pc;
  const d3 = 'seguimiento_dia_3_' + pc;
  if (lane === 'outreach') return toques >= 1 ? 'boarding_form_followup_touch2' : 'boarding_form_followup';
  if (lane === 'rescate') return toques >= 1 ? d3 : 'agenda_seg';
  return toques >= 1 ? d3 : d1;
}
function armarPlantilla(name, firstName) {
  const t = PLANTILLAS[name]; if (!t) return null;
  const nombre = String(firstName || '').trim().split(/\s+/)[0] || 'qué tal';
  const nVars = (t.body.match(/\{\{\d+\}\}/g) || []).length;
  const vars = nVars ? [nombre] : [];
  return { name, lang: t.lang, category: t.category, vars, texto: t.body.replace(/\{\{1\}\}/g, nombre) };
}

// sessionKey canónico = misma derivación que el rescate GHL (nsk) · con '+' desde Batch F.2 (2026-09-22)
function nsk(x){ x=(x||'').toString().replace(/[^0-9]/g,''); if(x.length===12 && x.startsWith('52')) x='521'+x.slice(2); return x; }
const flat = (n, key) => { try { return $(n).all().flatMap(i => (i.json && i.json[key]) || []); } catch(e){ return []; } };
const cfv = (c, id) => { for (const x of (c.customFields||[])) if (x.id===id) return x.value; return null; };
const truthy = v => v===true||v==='true'||(Array.isArray(v)&&v.includes('true'));
const now = Date.now();
const bookedOpps = flat('Query booked (OP·Bot)', 'opportunities');
const booked = new Set(bookedOpps.filter(o => BOOKED_STAGE_IDS.includes(o.pipelineStageId)).map(o => o.contactId));
const gate = (c) => {
  if (booked.has(c.id)) return false;
  if ((c.tags || []).map(t => String(t).toLowerCase()).includes('bot_pausado')) return false;  // PRE-BSP-0923 · lo tiene un asesor
  let toq = cfv(c, T); toq = (toq===null||toq===''||(Array.isArray(toq)&&!toq.length))?0:Number(toq);
  if (toq >= 2) return false;                       // TOPE GLOBAL 2 (outreach+rescate+nurturing)
  const est = (cfv(c, E)||'').toString().trim();
  if (TERMINAL.includes(est)) return false;
  const ut = cfv(c, ULT_TOQUE); const tu = ut ? Date.parse(ut) : null;
  if (tu && (now - tu) < MIN_HORAS_ENTRE_TOQUES*36e5) return false;   // espaciado entre toques
  return true;
};
// Recencia por carril: rescate/nurturing miden la última actividad del lead; outreach mide el Touch 1
// (un lead de Form Meta todavía no escribió). Sin fecha → no se toca (históricos del import).
// ENFRIADO-0924: ≥24 h sin actividad del lead (rescate y nurturing)
const enfriado = (iso) => { const t = iso ? Date.parse(iso) : NaN; return !isNaN(t) && (now - t) >= 24*36e5; };
const reciente = (iso) => { const t = iso ? Date.parse(iso) : NaN; return !isNaN(t) && (now - t) <= RECENCIA_DIAS*864e5; };
const mk = (c, lane) => {
  const programa = cfv(c, PROGRAMA_FIELD);
  const plantilla = armarPlantilla(elegirPlantilla(lane, Number(cfv(c,T))||0, programa), c.firstName);
  const templateId = plantilla ? plantilla.name : null;   // el IF `Tiene templateId?` sigue mirando este campo
  return {
    plantilla,
    contactId: c.id,
    phone: c.phone,
    session_key: '+' + nsk(c.phone),
    firstName: c.firstName,
    programa: programa || '',
    templateId,
    lane,
    toques_actual: Number(cfv(c,T))||0
  };
};
const sel = new Map();
// prioridad 1: rescate (link_enviado=true, sin cita)
for (const c of flat('Query rescate','contacts')) { if (gate(c) && reciente(cfv(c,UAF)) && enfriado(cfv(c,UAF))) sel.set(c.id, mk(c,'rescate')); }
// prioridad 2: nurturing (estado activo, SIN link — los con link ya están en rescate)
for (const c of flat('Query nurturing','contacts')) { if (sel.has(c.id)) continue; if (truthy(cfv(c,L))) continue; if (gate(c) && reciente(cfv(c,UAF)) && enfriado(cfv(c,UAF))) sel.set(c.id, mk(c,'nurturing')); }
// prioridad 3: outreach Form Meta (Decisión B — consolida el carril de toques de W10; sólo si touch1 ya venció)
for (const c of flat('Query outreach (Form Meta)','contacts')) {
  if (sel.has(c.id)) continue;
  if (truthy(cfv(c,L))) continue;
  const t1 = cfv(c, TOUCH1); const due = t1 ? (Date.parse(t1) <= now) : false;
  if (due && reciente(t1) && gate(c)) sel.set(c.id, mk(c,'outreach'));
}
return [...sel.values()].map(json => ({ json }));  // 1 item/contacto; 1 msg/contacto/run

